//! Tool wire types native decodes or builds (queries and shared field types).
//!
//! Generated by `@octocodeai/config` (`generate:tool-contract`) in the same run
//! as the embedded contract (the runtime's build.rs refuses a mismatched
//! pair), so Rust never hand-declares a tool wire shape. Regenerate there;
//! never edit. The file holds only the generated types native source names and
//! what they reach: naming one it lacks fails to compile until the contract is
//! regenerated. A crate of its own, so a runtime edit does not re-expand and
//! re-check them.
#![allow(
    dead_code,
    clippy::all,
    clippy::use_self,
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    missing_docs,
    reason = "generated wire types: native reads only some fields, variants and conversions of each emitted type"
)]

include!("../../../../octocode-config/contract/tool_types.rs");
